/**
 * 设备投放任务，同设备同发布单最多一条。
 *
 * @param id            任务ID
 * @param releaseId     所属发布单ID
 * @param deviceId      设备ID
 * @param status        任务状态
 * @param firstResult   首次回执结果（SUCCESS/FAILED），未回执为 null
 * @param frozenChainId 任务创建时刻固化的签名证书链ID；该固件未启用证书时为 null。
 *                      事后链撤销/轮换不改变本快照，回执与复核始终按冻结链裁决
 */
public record RolloutTask(long id, long releaseId, String deviceId, TaskStatus status,
                          ReceiptResult firstResult, Long frozenChainId) {
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ReleaseOrder;
import com.example.starter.firmware.domain.RolloutTask;

/**
 * 投放任务视图。frozenChainVersion 为任务创建时刻固化的证书链版本（未启用证书时为 null）。
 */
public record TaskView(long taskId, long releaseId, String deviceId, String status,
                       String fromVersion, String toVersion,
                       Long frozenChainId, Integer frozenChainVersion) {

    public static TaskView of(RolloutTask task, ReleaseOrder order) {
        return new TaskView(task.id(), task.releaseId(), task.deviceId(), task.status().name(),
                order.fromVersion(), order.toVersion(), task.frozenChainId(), null);
    }

    /**
     * 携带冻结链版本号的视图（服务层补查证书链后使用）。
     */
    public static TaskView of(RolloutTask task, ReleaseOrder order, Integer frozenChainVersion) {
