/**
 * 拉取/启动时的设备信任集合校验：
 * 链授权集合非空时设备必须在集合内；集合为空（全开放）时设备必须有 trusted=true 的信任记录。
 * 信任记录显式 trusted=false 始终拒绝，即使设备位于链授权集合内。
 */
public void assertDeviceAccepted(FirmwareCertChain chain, String deviceId) {
    DeviceTrust trust = trustRepository.findByDevice(deviceId).orElse(null);
    if (trust != null && !trust.trusted()) {
        throw ApiException.unprocessable("DEVICE_NOT_TRUSTED",
                "设备最终信任状态为不信任: " + deviceId);
    }
    long scopeSize = chainDeviceRepository.countDevices(chain.id());
    if (scopeSize > 0) {
        if (!chainDeviceRepository.exists(chain.id(), deviceId)) {
            throw ApiException.unprocessable("DEVICE_NOT_IN_CERT_SCOPE",
                    "设备不在证书链版本 " + chain.chainVersion() + " 的授权集合内: " + deviceId);
        }
        return;
    }
    if (trust == null) {
        throw ApiException.unprocessable("DEVICE_TRUST_MISSING",
                "启用证书的固件要求设备登记信任锚: " + deviceId);
    }
}

