                """))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("FIRMWARE_INCOMPATIBLE"));

        // 未登记固件（未启用证书、未配置矩阵）的型号沿用历史放行
        registerDevice("d9", "d9", "m9", "1.0.0", 1);
